package com.example.screenstream
import android.app.Activity; import android.content.Intent; import android.media.projection.MediaProjectionManager; import android.os.Build; import android.os.Bundle; import android.widget.Button; import android.widget.EditText; import android.widget.LinearLayout; import androidx.activity.result.contract.ActivityResultContracts; import androidx.appcompat.app.AppCompatActivity; import androidx.core.app.ActivityCompat
class MainActivity : AppCompatActivity() {
    private lateinit var serverUrlInput: EditText; private lateinit var roomCodeInput: EditText
    private val screenCaptureLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result -> if (result.resultCode == Activity.RESULT_OK && result.data != null) { val intent = Intent(this, ScreenCaptureService::class.java).apply { putExtra(ScreenCaptureService.EXTRA_RESULT_CODE, result.resultCode); putExtra(ScreenCaptureService.EXTRA_RESULT_DATA, result.data); putExtra(ScreenCaptureService.EXTRA_SERVER_URL, serverUrlInput.text.toString()); putExtra(ScreenCaptureService.EXTRA_ROOM_CODE, roomCodeInput.text.toString()) }; if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) startForegroundService(intent) else startService(intent) } }
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }; serverUrlInput = EditText(this).apply { hint = "Server URL" }; roomCodeInput = EditText(this).apply { hint = "Room Code" }; val btn = Button(this).apply { text = "Start"; setOnClickListener { val pm = getSystemService(MEDIA_PROJECTION_SERVICE) as MediaProjectionManager; screenCaptureLauncher.launch(pm.createScreenCaptureIntent()) } }; root.addView(serverUrlInput); root.addView(roomCodeInput); root.addView(btn); setContentView(root); if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) ActivityCompat.requestPermissions(this, arrayOf(android.Manifest.permission.POST_NOTIFICATIONS), 1) }
}
